#requires -Version 5.1
[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$PackageRoot,[Parameter(Mandatory=$true)][string]$DeployScript)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$previous='C:\1-webapp\forwarder-production\release-forwarder-expert-workflow-fc00720-20260913153210';$previousPython=Join-Path $previous 'runtime\python.exe';$arguments='/d /c ""'+$previousPython+'"" -m waitress --listen=127.0.0.1:5101 backend.wsgi:app';$taskXml='<Task><Actions><Exec><Command>C:\Windows\System32\cmd.exe</Command><Arguments>'+$arguments+'</Arguments><WorkingDirectory>'+$previous+'</WorkingDirectory></Exec></Actions></Task>'
function New-State([string]$Path){@{iis_path=(Join-Path $previous 'dist');task_xml=$taskXml;task_running=$true;listener_up=$true;listener_runtime=$previousPython;db_revision='20260920_legal_customer_nullable_contact_names';health=$true;target_created=$false;target_active=$false}|ConvertTo-Json|Set-Content -LiteralPath $Path -Encoding UTF8}
$working=Join-Path ([IO.Path]::GetTempPath()) ('forwarder-pipeline-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $working|Out-Null
try{$state=Join-Path $working 'state.json';New-State $state;& $DeployScript -PackageRoot $PackageRoot -ValidateOnly -FixtureStatePath $state|Out-Null;& $DeployScript -PackageRoot $PackageRoot -Execute -ConfirmDeployment -FixtureStatePath $state|Out-Null;$result=Get-Content -Raw $state|ConvertFrom-Json;if(-not $result.target_active){throw 'execute fixture did not activate target'};Write-Output 'FULL_VALIDATEONLY_SIMULATION=PASS';Write-Output 'FULL_EXECUTE_SIMULATION=PASS';foreach($failure in @('BACKEND_STOP','PORT_RELEASE','BACKEND_START','LISTENER_VERIFY','IIS_SWITCH','INTERNAL_HEALTH','PUBLIC_HEALTH')){New-State $state;try{& $DeployScript -PackageRoot $PackageRoot -Execute -ConfirmDeployment -FixtureStatePath $state -FailAt $failure|Out-Null;throw ('failure not injected: '+$failure)}catch{$rolled=Get-Content -Raw $state|ConvertFrom-Json;if($rolled.iis_path -ne (Join-Path $previous 'dist') -or $rolled.task_xml -ne $taskXml -or -not $rolled.task_running -or -not $rolled.listener_up -or $rolled.listener_runtime -ne $previousPython -or -not $rolled.health -or $rolled.target_active){throw ('rollback invariant failed: '+$failure)}}};Write-Output 'ROLLBACK_SIMULATION=PASS';Write-Output 'TIMEOUTS=PASS'}finally{Remove-Item -LiteralPath $working -Recurse -Force}
